<style>
.review-page{padding:34px 0 80px}.review-hero{background:linear-gradient(125deg,#103d2a,#247a4c);color:#fff;padding:38px;border-radius:24px;margin:18px 0 28px;position:relative;overflow:hidden}.review-hero:after{content:"★";position:absolute;right:35px;top:-50px;font-size:220px;opacity:.08;pointer-events:none}.review-hero h1{color:#fff;font-size:clamp(2rem,4vw,3.1rem);margin:8px 0}.review-hero p{color:#d5f0df;max-width:650px}.review-eyebrow{font-size:.78rem;letter-spacing:.15em;text-transform:uppercase;font-weight:800;color:#b6edca}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:20px}.review-card,.review-form-card,.review-detail{background:#fff;border:1px solid #dce9e0;border-radius:20px;padding:26px;box-shadow:0 12px 32px rgba(14,60,35,.055)}.review-card{display:flex;flex-direction:column;gap:14px}.review-card-top,.review-actions,.review-meta{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.review-avatar{display:grid;place-items:center;background:#e3f3e9;color:#155a37;width:46px;height:46px;border-radius:15px;font-size:1.2rem;font-weight:800}.review-author{display:flex;align-items:center;gap:12px}.review-author strong{display:block}.review-author small,.review-muted{color:#62796c}.review-stars{color:#efa927;letter-spacing:.1em;font-size:1.3rem}.review-rating{font-weight:800;color:#165e39}.review-court{display:inline-flex;align-items:center;gap:6px;color:#237447;font-weight:700}.review-comment{color:#304c3b;line-height:1.75;white-space:pre-wrap;overflow-wrap:anywhere}.review-actions{justify-content:flex-start;margin-top:auto;padding-top:12px;border-top:1px solid #edf2ee}.review-link{color:#176a3f;font-weight:700;text-decoration:none}.review-link:hover{text-decoration:underline}.review-danger{background:#fff;color:#b43c3c;border:1px solid #f0cbcb;padding:10px 15px;border-radius:10px;cursor:pointer;font:inherit}.review-danger:hover{background:#fff2f2}.review-form-card,.review-detail{max-width:760px;margin:0 auto}.review-label{display:block;margin:22px 0 9px;font-weight:750;color:#234b35}.review-textarea{display:block;width:100%;min-height:155px;resize:vertical;padding:16px;border-radius:14px;border:1px solid #cbded0;font:inherit;box-sizing:border-box;background:#fbfdfb;color:#193a29}.review-textarea:focus{outline:3px solid #b6e6c8;border-color:#23834e}.review-rating-choices{display:flex;gap:8px;flex-wrap:wrap}.review-rating-choices input{position:absolute;opacity:0;width:1px;height:1px}.review-rating-choices label{display:grid;place-items:center;cursor:pointer;font-size:1.8rem;width:53px;height:53px;border:1px solid #d7e6dc;border-radius:13px;color:#aab8ae;background:#f7faf8;transition:.15s}.review-rating-choices input:checked+label{color:#edaa2c;background:#fff7e5;border-color:#edaa2c}.review-rating-choices input:focus-visible+label{outline:3px solid #66bb85}.review-rating-choices label:hover{transform:translateY(-2px);color:#edaa2c}.review-submit{border:0;background:#176b40;color:white;padding:13px 24px;border-radius:12px;font:inherit;font-weight:750;cursor:pointer}.review-submit:hover{background:#10532f}.review-form-actions{display:flex;gap:15px;align-items:center;flex-wrap:wrap;margin-top:24px}.review-alert{padding:14px 18px;border-radius:12px;margin:18px 0;background:#e8f7ed;color:#155d36}.review-alert.error{background:#fff1f1;color:#9d3030}.review-alert ul{margin:8px 0 0}.review-empty{text-align:center;padding:65px 25px;border:1px dashed #bfd6c5;border-radius:20px;background:#f8fcf9}.review-empty-icon{font-size:3rem;color:#edaa2c}.review-pagination{margin-top:28px}.review-detail .review-comment{font-size:1.08rem}.review-divider{height:1px;background:#e4eee7;margin:22px 0}.review-booking-pill{display:inline-block;background:#e5f3e9;border-radius:100px;padding:8px 14px;color:#175e37;font-weight:750}.review-back{display:inline-block;margin-bottom:16px}.review-note{font-size:.9rem;color:#657c6c;margin-top:7px}@media(max-width:600px){.review-hero{padding:27px 22px}.review-card,.review-form-card,.review-detail{padding:20px}.review-rating-choices label{width:45px;height:48px}}
</style>